 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The most frequent color is the field/background; add color 2 between
    # repeated non-background markers separated by one background cell.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] == row[c + 1] != bg:
                out[r][c] = 2
    return out
